// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ref, uint256 ethAmount) public {
        // Ensure ethAmount is reasonable
        vm.assume(ethAmount > 0 && ethAmount < 1e18);
        // Seed the market with a minimal amount to enable the contract
        vm.deal(address(this), 1 ether);
        c.seedMarket(1000);
        vm.deal(address(this), 1 ether);

        // First get free kilos for the caller
        c.getFreeKilo();

        // Buy drugs to have something to collect
        vm.deal(address(this), ethAmount);
        c.buyDrugs{value: ethAmount}();

        // Warp time to produce some drugs
        vm.warp(block.timestamp + 1000);

        // Record caller's claimedDrugs before collect
        uint256 claimedBefore = c.claimedDrugs(address(this));

        // Call collectDrugs
        c.collectDrugs(ref);

        // After collect, claimedDrugs[caller] should be zero because
        // the old claimedDrugs were converted to kilos.
        // In the buggy version, claimedDrugs[caller] is NOT reset,
        // so it would still have the old value plus any referral bonus
        // that the caller might get (if ref == caller, which we protect against).
        // So we check that claimedDrugs[caller] is exactly zero.
        uint256 claimedAfter = c.claimedDrugs(address(this));
        assertTrue(claimedAfter == 0, "claimedDrugs should be zero after collect");
    }
}

